CREATE SCHEMA IF NOT EXISTS ad_ops;
CREATE TABLE IF NOT EXISTS ad_ops.snapshots (snapshot_id BIGSERIAL PRIMARY KEY, platform TEXT NOT NULL, account_id TEXT NOT NULL, campaign_id TEXT NOT NULL, snapshot_date DATE NOT NULL, source_revision TEXT NOT NULL, metrics JSONB NOT NULL, complete BOOLEAN NOT NULL, UNIQUE(platform,account_id,campaign_id,snapshot_date,source_revision));
CREATE TABLE IF NOT EXISTS ad_ops.recommendations (recommendation_id BIGSERIAL PRIMARY KEY, snapshot_id BIGINT NOT NULL REFERENCES ad_ops.snapshots(snapshot_id), idempotency_key TEXT NOT NULL UNIQUE, action TEXT NOT NULL CHECK(action IN ('monitor','data_quality_review','optimization_review')), reasons JSONB NOT NULL, evidence JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ad_ops.approvals (approval_id BIGSERIAL PRIMARY KEY, recommendation_id BIGINT NOT NULL REFERENCES ad_ops.recommendations(recommendation_id), actor_id TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ad_ops.action_receipts (receipt_id BIGSERIAL PRIMARY KEY, approval_id BIGINT NOT NULL UNIQUE REFERENCES ad_ops.approvals(approval_id), external_action_id TEXT NOT NULL UNIQUE, before_state JSONB NOT NULL, after_state JSONB, verified_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_ad_ops_review ON ad_ops.recommendations(action,created_at);
